INSERT OR IGNORE INTO settings(key,value,updated_at,actor) VALUES('templates','{"salary_general":{"text":"您好，我們有底薪制(儲備培訓)、高獎金論件計酬及兼職，現場會有面試主管向您說明\n0900-1800，周休二日 見紅休","version":1},"work_general":{"text":"您好，\n我們是政府合法委託社會住宅包租代管業者，致力於推廣社會住宅政策\n服務過程不收仲介費服務費，都是由政府經費撥款\n\n工作內容\n1.社會住宅推廣解說\n2.協助民眾辦理社會住宅相關補助\n3.評估房屋市場行情\n4.協助客戶處理糾紛\n5.電話拜訪客戶了解客戶案例\n\n現場會有面試主管向您說明","version":1},"office_taichung":{"text":"您好，我們面試和上課，統一在北屯文心路，之後上班可以選就近的辦公室。","version":1},"office_nantou":{"text":"目前面試統一在台中/彰化，之後辦公可以在草屯辦公室","version":1},"reschedule_offer":{"text":"您好，要預約下次面試時間嗎?","version":1},"nantou_route":{"text":"您好，請問您是否方便前往台中/或彰化分公司進行面試？\n\n台中：台中市北屯區文心路四段698號6樓之1\n彰化：彰化市華山路37號11樓之4\n\n若您方便前往，我們將進一步提供您具體的面試時間。謝謝您","version":1},"weather_notice":{"text":"(如遇到國定假/颱風假會暫停面試，請再主動來訊預約)","version":1},"booking_success":{"text":"好的，已為您完成面試預約！\n預約編號：{{bookingId}}\n應徵職務：{{job}}\n面試日期：{{date}}\n面試時間：{{time}}\n面試地點：{{address}}\n\n{{arrival}}\n{{interviewerNote}}\n(如遇到國定假/颱風假會暫停面試，請再主動來訊預約)","version":1},"choose_slot":{"text":"您好，請選擇方便的面試日期與時間。我們會在您最後確認時完成預約。","version":1},"full":{"text":"這個時段的線上預約名額已滿，請選其他方便的時段，謝謝您！","version":1},"cutoff":{"text":"這個時段已截止預約，請重新選擇其他日期或時間。","version":1},"human":{"text":"好的，這個問題由招募同仁協助您，請稍候。","version":1},"missing_field":{"text":"您好，還需要您的{{field}}，麻煩補充一下，方便我們幫您安排面試。","version":1}}',unixepoch(),'bootstrap');
